module TopModule (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    output [3:0] q
);

    // Register to hold the current state of the shift register
    reg [3:0] reg;

    // Register to hold the previous state of the shift register
    reg [3:0] prev_reg;

    // Register to hold the value to be loaded into the shift register
    reg [3:0] load_value;

    // Generate the next value of the register based on the load and ena inputs
    always @(posedge clk) begin
        // If ena is high and both load and areset are low, the load input has higher priority
        if (ena && !load && !areset) begin
            load_value <= data;
        end else if (ena && load && areset) begin
            load_value <= reg;
        end else if (load) begin
            load_value <= data;
        end else if (!load) begin
            // No load, shift the register right
            reg <= {q[2:0], q[3]};
            prev_reg <= reg;
        end else if (areset) begin
            reg <= {4'b0000};
            prev_reg <= {4'b0000};
        end
    end

    // Assign the current register value to the output q
    assign q = reg;

endmodule
