    reg [0:NUM_CELLS-1] cells;

    // Initialize the cells to all zeros
    initial begin
        for (int i = 0; i < NUM_CELLS; i++) begin
            cells[i] = 0;
        end
    end

    // Rule 90 cellular automaton logic
    always @(posedge clk) begin
        if (load) begin
            // Load the data onto the cells
            cells <= data;
        end else begin
            // Apply Rule 90 to update the cells
            for (int i = 0; i < NUM_CELLS; i++) begin
                // Get the left and right cells
                reg [0:0] left = (i == 0) ? 1'b0 : cells[i-1];
                reg [0:0] right = (i == NUM_CELLS-1) ? 1'b0 : cells[i+1];

                // Calculate the center cell's next state
                reg [0:0] center_next = left ^ right;

                // Update the cell
                cells[i] = center_next;
            end
        end
    end

    // Output the cells to the q port
    assign q = cells;

