    FSMState current_state = StateA;

    // State A: Reset
    always @(posedge clk or posedge resetn) begin
        if (resetn) begin
            current_state <= StateA;
            f <= 0;
            g <= 0;
        end else if (current_state == StateA) begin
            current_state <= StateB;
            f <= 1;
            g <= 0;
        end
    end

    // State B: Monitor x and set f
    always @(posedge clk or posedge resetn) begin
        if (resetn) begin
            current_state <= StateA;
            f <= 0;
            g <= 0;
        end else if (current_state == StateB) begin
            if (x == 1) begin
                current_state <= StateC;
            end
            f <= 0;
            g <= 0;
